import { StyleSheet, } from 'react-native';

const styles = StyleSheet.create({
    container: {
        width: 300,
        height: 350,
        backgroundColor: 'rgba(0,0,0,0.8)',
        borderRadius: 20,
        borderWidth: 3,
        borderColor: '#356',
        position: 'absolute',
        alignItems: 'center',
        justifyContent: 'space-around',
        paddingBottom: 20
    },

    containerButton: {
        backgroundColor: 'rgba(0,0,0,0.8)',
        borderRadius: 20,
        borderWidth: 3,
        borderColor: '#356',
        position: 'absolute',
        alignItems: 'center',
        justifyContent: 'space-around',
        paddingBottom: 20
    },

    listText: {
        fontSize: 40,
        color: '#000',
        backgroundColor: '#fff',
        padding: 5,
        borderRadius: 10,
        margin: 20
    }, 

});
export { styles };
